import {dateKey,atDate,shift,diff,initial,safety,phase,plan,makeWorkout,stats,tonnage,timerRemaining,timerAction,restAfterSet,validate,LIBRARY,TEMPLATES} from './engine.mjs?v=1.0.3';
import {load,save,encrypt,decrypt,csv} from './storage.mjs?v=1.0.3';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>dateKey(), fmt=d=>atDate(d).toLocaleDateString('en-CA',{month:'short',day:'numeric'}), weekday=d=>atDate(d).toLocaleDateString('en-CA',{weekday:'short'});
let state,page='Today',libraryQuery='',statsPeriod='30',statsExercise='',statsPattern='',statsSeason='all',storageOK=true,readyOffline=false,queue=Promise.resolve(),toastTimeout;
const names={A:'Strength A',B:'Strength B',C:'Club accessories',E:'Easy aerobic',R:'Recovery',G:'Ultimate game'},glyph={A:'↗',B:'↗',C:'✦',E:'≈',R:'☾',G:'◎'};
const displayWeight=n=>Math.round(n*(state.settings.unit==='kg'?.45359237:1)*10)/10;
const storedWeight=n=>state.settings.unit==='kg'?n/.45359237:n;
const field=(name,label,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const check=(name,label,value=false)=>`<label class="check"><input name="${name}" type="checkbox" ${value?'checked':''}>${label}</label>`;
function notify(message){clearTimeout(toastTimeout);$('#toast').textContent=message;$('#toast').style.display='block';toastTimeout=setTimeout(()=>$('#toast').style.display='none',5500)}
async function persist(){const copy=structuredClone(state);queue=queue.catch(()=>{}).then(()=>save(copy));try{await queue;storageOK=true}catch(e){storageOK=false;notify('Could not save on this device. Export a backup now; changes may be lost.');throw e}}
function modal(title,body,onSubmit){const d=$('#modal');d.innerHTML=`<button class="close ghost" type="button" aria-label="Close dialog">×</button><h2>${title}</h2>${body}`;d.querySelector('.close').onclick=()=>d.close();const form=d.querySelector('form');if(form)form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type=submit]');if(b)b.disabled=true;try{await onSubmit(new FormData(form),form);d.close()}catch(err){notify(err.message);if(b)b.disabled=false}};d.showModal()}
function readiness(){return state.recovery.findLast(r=>r.date===today())}
function safeNotice(){const x=safety(readiness());return `<div class="notice ${x.level==='stop'?'danger':x.level==='caution'?'warning':''}"><strong>${x.level==='stop'?'Training paused':x.level==='unknown'?'Readiness needed':x.level==='caution'?'Take it easy':'Today’s training guardrails'}</strong><br>${esc(x.message)} ${x.level==='unknown'?'<button class="small ghost" data-act="readiness">Check in →</button>':''}</div>`}
function render(){document.body.className=`${state.settings.theme==='light'?'light':''} ${state.settings.reduced?'reduced':''}`;if(!state.onboarded){onboarding();return}const nav=[['Today','⌂'],['Schedule','▦'],['Train','↗'],['Stats','▥'],['Library','▤'],['Settings','⚙']];$('#app').innerHTML=`<div class="shell"><aside><div class="logo">CHAPS<b>GYM</b><small>YOUR PERFORMANCE CLUB</small></div><nav aria-label="Main navigation">${nav.map(([n,g])=>`<button data-page="${n}" class="${page===n?'active':''}" ${page===n?'aria-current="page"':''}><span class="navicon" aria-hidden="true">${g}</span>${n}</button>`).join('')}</nav><div class="asidefoot"><span class="live-dot"></span> LOCAL & PRIVATE<br>TRAIN SMART. PLAY MORE.<br><span id="aside-status">${navigator.onLine?'Connected':'Offline'}</span></div></aside><main><div class="topline"><span class="desktopdate">${new Date().toLocaleDateString('en-CA',{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</span><span class="badge">${readyOffline?'✓ OFFLINE READY':navigator.onLine?'● ON DEVICE':'● OFFLINE'} · ${phase(state,today()).toUpperCase()}</span></div>${!storageOK?'<div class="notice danger">Saving failed. Export your data before closing this app.</div>':''}${({Today:home,Schedule:schedule,Train:train,Stats:analytics,Library:library,Settings:settings})[page]()}</main></div><div id="timer"></div>`;bind();renderTimer()}
function heading(title,desc,action=''){return `<div class="pagehead"><div><div class="eyebrow">Ultimate performance coach</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function home(){const r=readiness(),p=plan(state,today(),14),current=p[0],safe=safety(r);const next=state.games.filter(g=>!g.cancelled&&g.date>=today()).sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||''))).at(0);const s=stats(state,shift(today(),-6),today());return heading('Your next level.','A little stronger. A little faster. Ready for the field.',`<button class="ghost" data-act="readiness">${r?'Edit readiness':'Check in'} ↗</button>`)+safeNotice()+`<div class="grid"><div class="stack"><section class="hero"><div class="content"><div class="eyebrow">${safe.level==='stop'?'Recovery is the priority':'Your session · '+weekday(today())+' '+fmt(today())}</div><span class="badge">${phase(state,today())==='offseason'?'BUILD YOUR BASE':'GAME-READY TRAINING'}</span><h2>${safe.level==='stop'?'Rest & reassess':names[current.kind]}</h2><p>${safe.level==='stop'?'Give your recovery the attention it needs.':esc(current.reason)}</p><button class="primary" data-act="start" data-kind="${current.kind}" ${['stop','unknown'].includes(safe.level)||['G','R'].includes(current.kind)||current.done?'disabled':''}>${current.done?'Session completed':current.kind==='E'?'Log conditioning':current.kind==='G'?'Game day':current.kind==='R'?'Recovery day':'Let’s train'} <span aria-hidden="true">→</span></button>${current.done?'<p class="smallprint">Your completed log is saved.</p>':''}</div></section><section class="card"><div class="cardhead"><h2>This week</h2><button class="small ghost" data-page="Schedule">View schedule →</button></div><div class="week">${p.slice(0,7).map(d=>`<div class="day ${d.date===today()?'today':''} ${d.kind==='G'?'game':''}"><span>${weekday(d.date).toUpperCase()}</span><b>${atDate(d.date).getDate()}</b><div class="dot" title="${names[d.kind]}">${d.done?'✓':glyph[d.kind]}</div><span style="margin-top:8px">${d.kind==='G'?'GAME':d.kind==='R'?'REST':d.kind==='E'?'AERO':d.kind==='C'?'CLUB':'STR '+d.kind}</span></div>`).join('')}</div></section><section class="card"><div class="cardhead"><h2>The work adds up</h2><span class="tag">LAST 7 DAYS</span></div><div class="metrics"><div class="metric"><strong>${s.sessions}</strong><span>sessions</span></div><div class="metric"><strong>${s.conditioning}<small> min</small></strong><span>easy + interval work</span></div><div class="metric"><strong>${Math.round(displayWeight(s.volume)).toLocaleString()}</strong><span>${state.settings.unit} external volume</span></div></div></section></div><div class="stack"><section class="card"><div class="cardhead"><h2>Read the room.</h2><span class="tag">READINESS</span></div><div class="metrics">${[['Energy',r?.energy],['Hip pain',r?.pain],['Leg soreness',r?.legs]].map(([n,v])=>`<div class="metric"><strong>${v??'—'}</strong><span>${n} / 10</span></div>`).join('')}</div><p class="smallprint sectiongap">High energy is good. High pain or soreness calls for more recovery.</p><button class="ghost" data-act="readiness">${r?'Update check-in':'How are you feeling?'} →</button></section><section class="card"><div class="eyebrow">Next time on the field</div><h2>${next?fmt(next.date):'No games ahead'}</h2><p>${next?`${esc(next.name)}<br><span class="muted">${next.time||'Time not set'} · ${next.duration} min · expected RPE ${next.intensity}</span>`:'Off-season is your chance to build a stronger engine.'}</p><button class="ghost" data-act="game">${next?'Edit your calendar':'Add a game'} →</button></section><section class="card"><div class="eyebrow">Stay in the game</div><h2>Your data. Your device.</h2><p class="smallprint">${state.settings.lastBackup?'Last backup download: '+new Date(state.settings.lastBackup).toLocaleDateString():'No backup downloaded yet. Protect your training history with an encrypted backup.'}</p><button class="small ghost" data-act="backup">Back up now ↗</button></section></div></div>`}
function schedule(){const p=plan(state,today(),14);return heading('Make room for more.','Your next 14 days adapt around the games you actually play.',`<button class="primary" data-act="game">+ Add game</button>`)+`<div class="notice">Suggestions refresh when games, readiness or availability change. Completed logs stay put. Moving a session is a preference; safety restrictions still apply.</div><div class="grid"><section class="card"><div class="cardhead"><h2>The next two weeks</h2><span class="tag">ROLLING PLAN</span></div><div class="list">${p.map(d=>`<div class="listrow" draggable="${!d.done&&d.kind!=='G'}" data-drag="${d.date}" data-drop="${d.date}"><div class="row"><div class="datebox">${weekday(d.date)}<strong>${atDate(d.date).getDate()}</strong></div><div><strong>${d.done?'✓ ':''}${names[d.kind]}</strong><p>${esc(d.reason)}</p><span class="tag">${d.phase}</span>${state.travel.includes(d.date)?'<span class="tag">TRAVEL</span>':''}${d.games.map(g=>`<p>${esc(g.name)} · ${g.time||'time not set'} <button class="small ghost" data-act="editgame" data-id="${g.id}">Edit / log result</button></p>`).join('')}</div></div>${!d.done&&d.kind!=='G'?`<button class="small ghost" data-act="move" data-date="${d.date}">Change</button>`:''}</div>`).join('')}</div></section><div class="stack"><section class="card"><h2>Season & availability</h2><form id="phase-form" class="formgrid"><label class="full">Phase<select name="phase">${[['auto','Automatic transition'],['offseason','Off-season'],['inseason','In-season']].map(([v,n])=>`<option value="${v}" ${state.settings.phase===v?'selected':''}>${n}</option>`).join('')}</select></label>${field('offseason','Off-season begins',state.settings.offseasonStart,'date','class="full"')}<button type="submit" class="primary full">Update phase</button></form><div class="divider"></div><button class="ghost" data-act="travel">Set travel / unavailable day</button><p class="smallprint sectiongap">Off-season: 2 strength + 2 easy aerobic exposures, optional club session. In-season: 2 strength + 1 easy aerobic, adjusted down for crowded game weeks.</p></section><section class="card"><h2>Games & results</h2>${state.games.length?state.games.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(g=>`<div class="historyitem"><strong>${esc(g.name)}</strong><p class="smallprint">${fmt(g.date)} · ${g.cancelled?'Cancelled':g.played?`Played · ${g.actualDuration??g.duration} min · RPE ${g.actualIntensity??g.intensity}`:'Scheduled'}</p><button class="small ghost" data-act="editgame" data-id="${g.id}">Edit / result</button></div>`).join(''):'<p class="muted">No games added.</p>'}</section></div></div>`}
function train(){if(state.active)return workout();return heading('Put in the work.','Two strong days. A better engine. Plenty left for the field.')+safeNotice()+`<div class="grid"><section class="stack">${['A','B','C','E'].map(k=>`<section class="card"><div class="cardhead"><div><div class="eyebrow">${k==='E'?'Conditioning':k==='C'?'Optional · 30 min':'Full body · 60–65 min'}</div><h2>${esc(state.settings.program[k].name)}</h2><p class="muted">${esc(state.settings.program[k].subtitle)}</p></div><button class="primary" data-act="start" data-kind="${k}" ${['unknown','stop'].includes(safety(readiness()).level)?'disabled':''}>Start →</button></div><p class="smallprint">${state.settings.program[k].ids.map(id=>esc(state.library.find(e=>e.id===id)?.name||id)).join(' · ')||'Start with 20–25 easy minutes at a pace where you can speak in full sentences.'}</p><button class="small ghost" data-act="program" data-kind="${k}">Edit template</button></section>`).join('')}</section><div class="stack"><section class="card"><h2>Recent sessions</h2>${state.sessions.length?state.sessions.slice().reverse().slice(0,12).map(w=>`<div class="historyitem"><div class="row between"><strong>${esc(w.name)}</strong><span class="tag">${fmt(w.date)}</span></div><p class="smallprint">${w.items.reduce((n,e)=>n+e.sets.filter(s=>s.done).length,0)} sets · ${Math.round(displayWeight(w.items.reduce((n,e)=>n+tonnage(e),0))).toLocaleString()} ${state.settings.unit} volume</p><button class="small ghost" data-act="history" data-id="${w.id}">View log</button></div>`).join(''):'<div class="empty">Your first session starts the story.<br>No demo logs are mixed into your history.</div>'}</section><section class="card"><h2>Conditioning log</h2><button class="ghost" data-act="conditioning">+ Add conditioning</button>${state.conditioning.slice().reverse().slice(0,6).map(c=>`<div class="historyitem"><strong>${c.minutes} min · ${esc(c.type)}</strong><p class="smallprint">${fmt(c.date)} · RPE ${c.rpe}${c.distance?' · '+c.distance+' '+esc(c.distanceUnit||'km'):''}<br>${esc(c.notes)}</p></div>`).join('')}</section></div></div>`}
function workout(){const w=state.active;const safe=safety(readiness());return heading(esc(w.name),'Your progress saves after every entry.',`<button class="primary" data-act="finish">Finish session</button>`)+safeNotice()+`<div class="notice">Warm up 5–8 minutes, then use lighter practice sets. Leave 2–3 RIR. ${state.settings.deload?'Deload active: fewer sets and lighter loads.':''} ${phase(state,w.date)==='inseason'?'Maintain strength; avoid grinding and prioritize games.':'Build reps before increasing load.'}</div><div class="row wrap" style="margin-bottom:20px">${check('workoutAuto','Auto rest timer',w.autoRest)}${check('superset','Superset pairs (1+2, 3+4…)',w.superset)}<label style="max-width:170px">Transition rest (seconds)<input id="transition-rest" type="number" min="0" max="300" value="${w.transitionRest??15}"></label><button class="small ghost" data-act="manualtimer">Start timer</button><button class="small ghost" data-act="addexercise">+ Exercise</button></div>${w.items.map((e,i)=>`<section class="card exercise ${e.omitted?'muted':''}"><div class="cardhead"><div class="row"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)} ${e.omitted?'· omitted':''}</h3><span class="tag">${esc(e.pattern)}</span> <span class="tag">${esc(e.equipment)}</span> ${e.unilateral?'<span class="tag">REPS / SIDE</span>':''}</div></div><button class="small ghost" data-act="swap" data-index="${i}">Swap / omit</button></div><p class="smallprint">${esc(e.cues)}</p>${!e.omitted?`<p class="smallprint">${esc(e.advice?.message||'Use a comfortable load.')} ${e.factor===4?'Weight per dumbbell; total volume counts both dumbbells and both sides.':e.factor===2&&!e.unilateral?'Weight per dumbbell; volume counts both dumbbells.':e.unilateral?'Volume counts both sides.':''}</p><div class="sets"><div class="setrow labels"><span>SET</span><span>${e.bodyweight?'ADDED '+state.settings.unit.toUpperCase():state.settings.unit.toUpperCase()}</span><span>${e.unit==='seconds'?'SEC / SIDE':e.impact&&e.bodyweight?'CONTACTS':'REPS'+(e.unilateral?' / SIDE':'')}</span><span>RIR</span><span>RPE</span><span>DONE</span></div>${e.sets.map((s,j)=>`<div class="setrow ${s.done?'complete':''}"><span class="smallprint">${j+1}</span><input type="number" inputmode="decimal" min="0" max="2000" step="0.5" aria-label="${esc(e.name)} set ${j+1} weight in ${state.settings.unit}" value="${displayWeight(s.weight)}" data-set="${i},${j},weight" ${e.bodyweight?'disabled':''}><input type="number" inputmode="numeric" min="1" max="200" aria-label="${esc(e.name)} set ${j+1} ${e.unit==='seconds'?'seconds':'reps'}" value="${s.reps}" data-set="${i},${j},reps"><input type="number" inputmode="numeric" min="0" max="10" aria-label="${esc(e.name)} set ${j+1} reps in reserve" value="${s.rir}" data-set="${i},${j},rir"><input type="number" inputmode="decimal" min="0" max="10" step="0.5" aria-label="${esc(e.name)} set ${j+1} RPE" value="${s.rpe}" data-set="${i},${j},rpe"><button data-act="setdone" data-index="${i}" data-setindex="${j}" aria-label="${s.done?'Undo':'Complete'} ${esc(e.name)} set ${j+1}" aria-pressed="${s.done}">${s.done?'✓':'○'}</button></div>`).join('')}</div><div class="row wrap sectiongap"><button class="small ghost" data-act="addset" data-index="${i}">+ Set</button><button class="small ghost" data-act="copyset" data-index="${i}">Copy previous set</button><label style="max-width:150px">Rest seconds<input type="number" min="0" max="3600" step="15" value="${e.rest}" data-rest="${i}"></label><button class="small ghost" data-act="exrest" data-index="${i}">Rest ${e.rest}s</button></div>`:''}</section>`).join('')}${!w.items.length?'<div class="notice warning">No exercises fit your current safety and equipment settings. Rest, or add an appropriate upper-body exercise.</div>':''}<section class="card"><label>Session notes<textarea id="session-notes">${esc(w.notes)}</textarea></label><div class="actions"><button class="primary" data-act="finish">Finish & save</button><button class="ghost" data-act="discard">Discard session</button></div></section>`}
function analytics(){const period=Number(statsPeriod),from=statsPeriod==='all'?'2000-01-01':shift(today(),-period+1);const filtered=statsSeason==='all'?state:{...state,sessions:state.sessions.filter(w=>(w.phase||phase(state,w.date))===statsSeason),conditioning:state.conditioning.filter(w=>(w.phase||phase(state,w.date))===statsSeason),games:state.games.filter(w=>(w.phase||phase(state,w.date))===statsSeason)};const s=stats(filtered,from,today(),statsExercise,statsPattern);const history=filtered.sessions.filter(w=>w.date>=from&&w.date<=today());const bars=Array.from({length:12},(_,i)=>{const end=shift(today(),-(11-i)*7),start=shift(end,-6);return {date:start,value:stats(filtered,start,end,statsExercise,statsPattern).volume}});const max=Math.max(1,...bars.map(x=>x.value));const lifts=state.library.filter(e=>!e.bodyweight&&!e.impact&&(!statsExercise||e.id===statsExercise)&&(!statsPattern||e.pattern===statsPattern)).map(e=>{const sets=history.flatMap(w=>w.items.filter(x=>x.id===e.id&&!x.omitted).flatMap(x=>x.sets.filter(y=>y.done&&y.weight>0)));return {e,best:Math.max(0,...sets.map(x=>x.weight)),estimate:Math.max(0,...sets.filter(x=>x.reps<=10&&x.reps>0).map(x=>x.weight*(1+x.reps/30)))}}).filter(x=>x.best);return heading('Proof of the work.','Progress you can see. Context you can trust.')+`<div class="filters"><label>Period<select id="stats-period">${[['1','Today'],['7','7 days'],['30','30 days'],['90','3 months'],['365','Year'],['all','All time']].map(([v,n])=>`<option value="${v}" ${statsPeriod===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Exercise<select id="stats-exercise"><option value="">All exercises</option>${state.library.map(e=>`<option value="${e.id}" ${statsExercise===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label><label>Movement<select id="stats-pattern"><option value="">All movements</option>${[...new Set(state.library.map(e=>e.pattern))].map(p=>`<option ${statsPattern===p?'selected':''}>${esc(p)}</option>`).join('')}</select></label><label>Season<select id="stats-season">${[['all','All seasons'],['offseason','Off-season'],['inseason','In-season']].map(([v,n])=>`<option value="${v}" ${statsSeason===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="metrics" style="margin-bottom:22px"><div class="metric"><strong>${Math.round(displayWeight(s.volume)).toLocaleString()}</strong><span>${state.settings.unit} external volume</span></div><div class="metric"><strong>${s.sessions}</strong><span>completed sessions · ${s.sets} sets</span></div><div class="metric"><strong>${s.conditioning}</strong><span>conditioning minutes</span></div></div><div class="grid"><div class="stack"><section class="card"><div class="cardhead"><h2>12-week lifting volume</h2><span class="tag">${state.settings.unit.toUpperCase()}</span></div><div class="chart" role="img" aria-label="Weekly external lifting volume. Exact values follow in table.">${bars.map(b=>`<div class="bar" style="height:${Math.max(1,b.value/max*100)}%" title="${fmt(b.date)}: ${Math.round(displayWeight(b.value))} ${state.settings.unit}"></div>`).join('')}</div><div class="chart-labels"><span>${fmt(bars[0].date)}</span><span>${fmt(today())}</span></div><details><summary>Weekly values</summary><table><thead><tr><th>Week starting</th><th>Volume</th></tr></thead><tbody>${bars.map(b=>`<tr><td>${fmt(b.date)}</td><td>${Math.round(displayWeight(b.value))} ${state.settings.unit}</td></tr>`).join('')}</tbody></table></details><p class="smallprint sectiongap">Volume = load × reps × implement/side multiplier. Excludes bodyweight, timed holds and power drills. It describes lifting workload, not overall athletic performance. Chart always shows 12 weeks; summary cards use your selected period.</p></section><section class="card"><h2>Lift records</h2>${lifts.length?`<div class="tablewrap"><table><thead><tr><th>Exercise</th><th>Best load</th><th>Est. 1RM</th></tr></thead><tbody>${lifts.map(x=>`<tr><td>${esc(x.e.name)}</td><td>${displayWeight(x.best)} ${state.settings.unit}</td><td>${displayWeight(x.estimate)} ${state.settings.unit}</td></tr>`).join('')}</tbody></table></div><p class="smallprint sectiongap">Epley estimate from sets of ≤10 reps. Approximate, especially at higher RIR. Dumbbell estimates are per dumbbell; no max testing is prescribed.</p>`:'<div class="empty">Complete a loaded session to see records here.</div>'}</section></div><div class="stack"><section class="card"><h2>Field & impact</h2><div class="metrics"><div class="metric"><strong>${s.games.length}</strong><span>games played</span></div><div class="metric"><strong>${s.games.reduce((n,g)=>n+Number(g.actualDuration??g.duration),0)}</strong><span>game minutes</span></div><div class="metric"><strong>${s.contacts}</strong><span>logged jump contacts</span></div></div><p class="smallprint sectiongap">Game effort: ${s.games.length?(s.games.reduce((n,g)=>n+Number(g.actualIntensity??g.intensity),0)/s.games.length).toFixed(1):'—'} average RPE. Game impact contributes stress but is not converted into invented jump counts.</p><p class="smallprint">Training frequency: ${history.filter(w=>diff(today(),w.date)<7).length} sessions in the last 7 days. Suggestions are flexible; missed sessions are never marked completed.</p></section><section class="card"><h2>Recovery trend</h2>${state.recovery.filter(r=>r.date>=from&&r.date<=today()).slice(-10).reverse().map(r=>`<div class="historyitem"><strong>${fmt(r.date)}</strong><p class="smallprint">Hip ${r.pain}/10 · energy ${r.energy}/10 · legs ${r.legs}/10<br>${esc(r.notes||'')}</p></div>`).join('')||'<p class="muted">Daily check-ins will appear here.</p>'}</section></div></div>`}
function library(){const q=libraryQuery.toLowerCase();const items=state.library.filter(e=>(e.name+' '+e.pattern+' '+e.equipment).toLowerCase().includes(q));return heading('Know your movement.','Purpose-led options. Your equipment. Your comfort.',`<button class="primary" data-act="newexercise">+ Exercise</button>`)+`<label style="margin-bottom:20px">Search exercises, equipment or movement<input id="library-search" type="search" value="${esc(libraryQuery)}" placeholder="Try hip, pull, dumbbells…"></label><div class="grid">${items.map(e=>`<section class="card"><div class="cardhead"><h3>${esc(e.name)}</h3><button class="small ghost" data-act="editexercise" data-id="${e.id}">Edit</button></div><div class="row wrap"><span class="tag">${esc(e.pattern)}</span><span class="tag">${esc(e.equipment)}</span>${e.lower?'<span class="tag">HIP / LOWER BODY</span>':''}${e.impact?'<span class="tag">CLEARANCE REQUIRED</span>':''}</div><p class="smallprint sectiongap">${esc(e.cues)}</p><p class="smallprint">${e.sets} × ${e.reps} ${e.unit||'reps'}${e.unilateral?' / side':''} · ${e.rest}s rest${e.range?' · progression range '+e.range.join('–'):''}<br>${e.bodyweight?'Bodyweight / contacts tracked separately.':'Load multiplier: '+e.factor+' (implements × sides).'}<br>Alternatives: ${(e.swaps||[]).map(id=>esc(state.library.find(x=>x.id===id)?.name||id)).join(', ')||'Omit; no automatic substitute.'}</p><details><summary>Intensity & tolerance</summary><p class="smallprint">Lower intensity: fewer sets, lighter load, easier comfortable range, extra rest. Higher intensity: only progress when recovered, symptom-stable and technically ready. ${e.lower?'Hip tolerance is individual; omit if pain increases.':''} ${e.impact?'Maximal jumps use 2–5 quality reps; low-intensity reactive contacts are a separate exposure. Never substitute more impact during symptoms.':''} Omission is always available.</p></details></section>`).join('')}</div>`}
function settings(){return heading('Your club. Your rules.','Keep it personal. Keep it portable.')+`<div class="grid"><div class="stack"><section class="card"><h2>Preferences</h2><form id="settings-form" class="formgrid"><label>Units<select name="unit"><option value="lb" ${state.settings.unit==='lb'?'selected':''}>Pounds (lb)</option><option value="kg" ${state.settings.unit==='kg'?'selected':''}>Kilograms (kg)</option></select></label><label>Appearance<select name="theme"><option value="dark" ${state.settings.theme==='dark'?'selected':''}>Neon dark</option><option value="light" ${state.settings.theme==='light'?'selected':''}>Accessible light</option></select></label><div class="full">${check('autoRest','Auto-start rest after sets',state.settings.autoRest)}${check('sound','Enable foreground timer sound',state.settings.sound)}${check('vibrate','Enable vibration where supported',state.settings.vibrate)}${check('reduced','Reduce motion',state.settings.reduced)}${check('clearance','I have clearance for lower-body and impact progression',state.settings.clearance)}${check('deload','Deload week: reduce sets and load',state.settings.deload)}</div><label class="full">Training priorities<textarea name="priorities">${esc(state.settings.priorities)}</textarea></label><button class="primary full" type="submit">Save preferences</button></form><p class="smallprint sectiongap">Alerts need this preference and browser support. iPhone background sound and vibration are not guaranteed. Countdown uses a saved deadline and recovers on reopen.</p></section><section class="card"><h2>Your equipment</h2><form id="equipment-form">${[...new Set([...LIBRARY.map(e=>e.equipment),...state.library.map(e=>e.equipment)])].map(n=>check('equipment',esc(n),state.settings.equipment.includes(n)).replace('name="equipment"',`name="equipment" value="${esc(n)}"`)).join('')}<button type="submit" class="primary sectiongap">Save equipment</button></form></section></div><div class="stack"><section class="card"><div class="eyebrow">Data stays on this device</div><h2>Backup & restore</h2><p>Your logs live in this browser’s local database. No analytics, trackers, paid APIs or workout-data uploads.</p><p class="smallprint">${state.settings.lastBackup?'Last encrypted download: '+new Date(state.settings.lastBackup).toLocaleString():'No backup downloaded yet.'} Downloading starts a file save; check Files to confirm it exists. Copy it to iCloud Drive manually.</p><div class="actions"><button class="primary" data-act="backup">Encrypted backup</button><button class="ghost" data-act="restore">Restore backup</button><button class="ghost" data-act="csv">Export CSV</button></div><p class="smallprint sectiongap">Keep your passphrase separately. It cannot be reset or recovered. Clearing Safari data, deleting the installed app, or device loss may erase your local history. Back up weekly and after important sessions. CSV is unencrypted.</p></section><section class="card"><h2>Install on iPhone</h2><ol class="smallprint"><li>Open this app’s hosted link in Safari.</li><li>Use Share → Add to Home Screen → Add.</li><li>Open Chaps Gym from the Home Screen while online once. Wait for “Offline ready.”</li><li>Use that installed app consistently; make a backup before changing browsers or installations.</li></ol><p class="smallprint">Free local operation, no training subscription or AI connection needed. Private hosting may require sign-in to open online. Offline use works after the app shell is cached. No automatic iCloud sync is promised.</p><button class="ghost" data-act="persist">Request durable device storage</button><p id="persistence-status" class="smallprint sectiongap"></p></section><section class="card"><h2>Training rules</h2><p class="smallprint">This deterministic planner is a conservative aid, not a diagnosis or a replacement for individualized coaching. Strength progression adds reps first, then suggests a small load increase in off-season. Game-adjacent days block heavy lower-body and impact exercises. Daily safety screening always applies.</p><p class="smallprint">Sources: <a href="https://www.nhs.uk/symptoms/hip-pain/" target="_blank" rel="noreferrer">NHS hip pain guidance</a> · <a href="https://acsm.org/resistance-training-guidelines-update-2026/" target="_blank" rel="noreferrer">ACSM resistance training guidance</a>. Scheduling and symptom thresholds are conservative app rules, not clinically validated predictions.</p></section></div></div>`}
function onboarding(){const d=new Date();let offset=(3-d.getDay()+7)%7;if(offset===0)offset=7;const next=shift(today(),offset);$('#app').innerHTML=`<div class="onboarding"><div class="logo">CHAPS<b>GYM</b></div><div class="eyebrow">Welcome to your performance club</div><h1>Train smart.<br>Play more.</h1><p class="muted">A private, offline training companion. Set up your season on this device; your history starts empty.</p><section class="card"><form id="onboard-form" class="formgrid">${field('game','Final game before off-season',next,'date')}<label>Game time (optional)<input name="time" type="time"></label><label class="full">Starting phase<select name="phase"><option value="auto">One final game, then off-season</option><option value="offseason">Already off-season</option><option value="inseason">Stay in-season</option></select></label><div class="full">${check('clearance','I have been cleared for lower-body lifting, running and jumping')}${check('backup','I understand backups are manual and passphrase-protected',true)}</div><p class="smallprint full">No health history or screenshots are uploaded. Symptoms still override clearance. You can edit dates, exercises and training preferences at any time.</p><button class="primary full" type="submit">Enter Chaps Gym →</button></form></section></div>`;$('#onboard-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(!f.has('backup'))return notify('Please acknowledge manual backups.');state.settings.clearance=f.has('clearance');state.settings.phase=f.get('phase');if(f.get('phase')==='auto'){if(!f.get('game'))return notify('Set a final game date.');state.games.push({id:crypto.randomUUID(),date:f.get('game'),time:f.get('time'),name:'Ultimate game',intensity:7,duration:90,cancelled:false,played:false});state.settings.offseasonStart=shift(f.get('game'),1)}state.onboarded=true;await persist();render();readinessDialog()}}
function readinessDialog(){const r=readiness()||{pain:0,energy:7,legs:2,sleep:7};modal('How are you feeling?',`<form class="formgrid">${field('pain','Hip pain / 10',r.pain,'number','min="0" max="10" required')}${field('energy','Energy / 10',r.energy,'number','min="0" max="10" required')}${field('legs','Leg soreness / 10',r.legs,'number','min="0" max="10" required')}${field('sleep','Sleep hours',r.sleep,'number','min="0" max="24" step="0.5" required')}<div class="full">${check('severe','Severe or sudden intense pain',r.severe)}${check('limp','Limping',r.limp)}${check('weightBearing','Difficulty bearing weight',r.weightBearing)}${check('worse','Symptoms are worsening',r.worse)}</div><label class="full">Recovery notes<textarea name="notes">${esc(r.notes||'')}</textarea></label><p class="smallprint full">Severe symptoms stop training recommendations. Worsening symptoms restrict lower-body work and prompt reassessment.</p><button class="primary full" type="submit">Save readiness</button></form>`,async f=>{const v={date:today(),pain:+f.get('pain'),energy:+f.get('energy'),legs:+f.get('legs'),sleep:+f.get('sleep'),notes:f.get('notes'),severe:f.has('severe'),limp:f.has('limp'),weightBearing:f.has('weightBearing'),worse:f.has('worse')};state.recovery=state.recovery.filter(r=>r.date!==today());state.recovery.push(v);if(safety(v).level==='stop')state.timer=null;await persist();render();notify(safety(v).level==='stop'?'Training paused. Please seek urgent assessment.':'Readiness saved. Your plan is updated.')})}
function gameDialog(id){const g=state.games.find(g=>g.id===id)||{date:today(),name:'Ultimate game',intensity:7,duration:90,time:''};modal(id?'Game details & result':'Add a game',`<form class="formgrid">${field('name','Game / league name',g.name,'text','required maxlength="100"')}${field('date','Date',g.date,'date','required')}${field('time','Time (optional)',g.time,'time')}${field('duration','Expected minutes',g.duration,'number','min="1" max="480" required')}${field('intensity','Expected RPE / 10',g.intensity,'number','min="1" max="10" required')}${!id?`<label>Repeat weekly<select name="repeat"><option value="1">One game</option><option value="4">4 weeks</option><option value="8">8 weeks</option><option value="12">12 weeks</option></select></label>`:''}<div class="full">${check('cancelled','Cancelled',g.cancelled)}${check('played','Played — include in analytics',g.played)}</div>${field('actualDuration','Actual minutes',g.actualDuration??g.duration,'number','min="0" max="480"')}${field('actualIntensity','Actual RPE',g.actualIntensity??g.intensity,'number','min="1" max="10"')}<button class="primary full" type="submit">Save & recalculate</button></form>`,async f=>{const n={id:id||crypto.randomUUID(),name:f.get('name'),date:f.get('date'),time:f.get('time'),duration:+f.get('duration'),intensity:+f.get('intensity'),actualDuration:+f.get('actualDuration'),actualIntensity:+f.get('actualIntensity'),cancelled:f.has('cancelled'),played:f.has('played')};if(id)state.games=state.games.map(x=>x.id===id?n:x);else for(let i=0;i<+(f.get('repeat')||1);i++)state.games.push({...n,id:crypto.randomUUID(),date:shift(n.date,i*7)});await persist();render();notify('Game saved. Future suggestions recalculated.')})}
function conditioningDialog(){const safe=safety(readiness());if(['unknown','stop'].includes(safe.level))return notify(safe.message);const weeks=Math.floor(state.conditioning.filter(c=>c.type==='Easy aerobic'&&c.rpe<=4&&c.talk).length/2);const minutes=Math.min(35,20+weeks*5);modal('Build your engine',`<form class="formgrid"><div class="notice full">Start with ${minutes} easy minutes, full-sentence talk test / RPE 2–4. Increase by about 5 minutes a week only if well recovered. Intervals are optional after several symptom-stable weeks; do not introduce them during a flare or near games.</div>${field('date','Date',today(),'date','required')}<label>Type<select name="type"><option>Easy aerobic</option><option>Intervals</option><option>Benchmark</option></select></label>${field('minutes','Total minutes',minutes,'number','min="1" max="600" required')}${field('rpe','Session RPE / 10',3,'number','min="1" max="10" required')}${field('distance','Distance (optional)',0,'number','min="0" max="200" step="0.01"')}<label>Distance unit<select name="distanceUnit"><option>km</option><option>mi</option></select></label>${field('speed','Treadmill speed (same unit/hour)',0,'number','min="0" max="40" step="0.1"')}${field('incline','Incline %',0,'number','min="0" max="30" step="0.5"')}<label class="full">Interval structure / benchmark / notes<textarea name="notes" placeholder="Example: 5 min warm-up, 4 × 1 min moderate / 2 min easy, 5 min cool-down. Only if cleared, symptom-stable and recovered."></textarea></label>${check('talk','Could speak in full sentences',true)}<button class="primary full" type="submit">Save conditioning</button></form>`,async f=>{const current=safety(readiness());if(['unknown','stop'].includes(current.level))throw Error(current.message);if(f.get('type')!=='Easy aerobic'&&(current.level==='caution'||!state.settings.clearance||state.games.some(g=>!g.cancelled&&Math.abs(diff(g.date,today()))<=1)))throw Error('Intervals and benchmarks are restricted by today’s symptoms, clearance or game window. Choose easy aerobic work only if comfortable.');state.conditioning.push({id:crypto.randomUUID(),date:f.get('date'),type:f.get('type'),minutes:+f.get('minutes'),rpe:+f.get('rpe'),distance:+f.get('distance'),distanceUnit:f.get('distanceUnit'),speed:+f.get('speed'),incline:+f.get('incline'),talk:f.has('talk'),notes:f.get('notes')});await persist();render();notify('Conditioning saved.')})}
function mayTrain(e){const safe=safety(readiness());if(['stop','unknown'].includes(safe.level))throw Error(safe.message);const near=state.games.some(g=>!g.cancelled&&Math.abs(diff(g.date,today()))<=1),crowded=state.games.filter(g=>!g.cancelled&&Math.abs(diff(g.date,today()))<=3).length>=3;if(e.lower&&(safe.level==='caution'||near||crowded||!state.settings.clearance))throw Error('Lower-body work is restricted by symptoms, game proximity or clearance. Omit this exercise today.');if(e.impact&&(!state.settings.clearance||safe.level!=='ready'||near||crowded))throw Error('Impact work is restricted today. Omit it; do not swap to another impact drill.');return true}
async function start(kind){if(state.active){page='Train';render();return notify('Resume or finish your current session first.')}if(kind==='E')return conditioningDialog();if(!['A','B','C'].includes(kind))return;if(!readiness())return readinessDialog();state.active=makeWorkout(state,kind);await persist();page='Train';render()}
function moveDialog(date){modal('Adjust your schedule',`<form class="formgrid"><p class="smallprint full">Completed sessions are never moved. Overrides still respect symptom and game restrictions.</p><label class="full">Session<select name="kind">${['A','B','C','E','R'].map(k=>`<option value="${k}">${names[k]}</option>`).join('')}</select></label>${field('target','Date',date,'date','required')}<button class="primary full" type="submit">Move / set session</button></form>`,async f=>{const target=f.get('target');if(state.sessions.some(w=>w.date===target)||state.games.some(g=>!g.cancelled&&g.date===target))throw Error('That date has a completed session or game. Choose another date.');if(date!==target)state.overrides[date]='R';state.overrides[target]=f.get('kind');await persist();render()})}
function exerciseDialog(id){const e=state.library.find(e=>e.id===id)||{id:crypto.randomUUID(),name:'',pattern:'Core',equipment:'Floor',sets:2,reps:10,rest:60,factor:1,cues:'',swaps:[]};modal(id?'Edit exercise':'New exercise',`<form class="formgrid">${field('name','Name',e.name,'text','required maxlength="100"')}${field('pattern','Movement / goal',e.pattern,'text','required maxlength="50"')}${field('equipment','Equipment',e.equipment,'text','required maxlength="50"')}${field('sets','Default sets',e.sets,'number','min="1" max="12" required')}${field('reps','Reps / contacts / hold seconds',e.reps,'number','min="1" max="200" required')}${field('rest','Default rest seconds',e.rest,'number','min="0" max="3600" required')}${field('factor','Load multiplier (implements × sides)',e.factor,'number','min="1" max="4" required')}<label>Rep unit<select name="unit"><option value="reps" ${e.unit!=='seconds'?'selected':''}>Reps / contacts</option><option value="seconds" ${e.unit==='seconds'?'selected':''}>Timed hold seconds</option></select></label><div class="full">${check('lower','Lower-body / hip loading',e.lower)}${check('impact','Impact / explosive work',e.impact)}${check('bodyweight','Bodyweight (exclude tonnage)',e.bodyweight)}${check('unilateral','Reps entered per side',e.unilateral)}</div><label class="full">Cues / tolerance notes<textarea name="cues">${esc(e.cues)}</textarea></label><button class="primary full" type="submit">Save exercise</button></form>`,async f=>{const n={...e,name:f.get('name'),pattern:f.get('pattern'),equipment:f.get('equipment'),sets:+f.get('sets'),reps:+f.get('reps'),rest:+f.get('rest'),factor:+f.get('factor'),unit:f.get('unit'),lower:f.has('lower'),impact:f.has('impact'),bodyweight:f.has('bodyweight'),unilateral:f.has('unilateral'),cues:f.get('cues')};if(id)state.library=state.library.map(x=>x.id===id?n:x);else state.library.push(n);if(!state.settings.equipment.includes(n.equipment))state.settings.equipment.push(n.equipment);await persist();render()})}
function swapDialog(index,add=false){const old=state.active?.items[index];const candidates=state.library.filter(e=>state.settings.equipment.includes(e.equipment)&&(!old||e.pattern===old.pattern||(old.swaps||[]).includes(e.id)));modal(add?'Add exercise':'Purpose-based swap',`<form><p class="smallprint">Swaps must fit your safety and equipment settings. Omit if no comfortable alternative exists. Lower intensity means less load or fewer sets; it does not mean training through pain.</p><label>Exercise<select name="id">${!add?'<option value="omit">Omit this exercise</option>':''}${candidates.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.equipment)}</option>`).join('')}</select></label><div class="actions"><button class="primary" type="submit">${add?'Add exercise':'Apply swap'}</button></div></form>`,async f=>{if(f.get('id')==='omit')state.active.items[index].omitted=true;else{const e=state.library.find(e=>e.id===f.get('id'));if(!e)throw Error('Choose an exercise.');mayTrain(e);const n={...structuredClone(e),sets:Array.from({length:e.sets},()=>({weight:0,reps:e.reps,rir:3,rpe:7,done:false})),omitted:false};if(add)state.active.items.push(n);else{if(old.sets.some(s=>s.done))throw Error('Logged sets are preserved. Omit the remaining work, then add your alternative as a new exercise.');state.active.items[index]=n;}}await persist();render()})}
function programDialog(kind){const p=state.settings.program[kind];modal('Edit '+esc(p.name),`<form>${field('name','Session name',p.name,'text','required maxlength="80"')}<p class="smallprint sectiongap">Choose exercises; order follows this list. You can swap or omit during a workout.</p>${state.library.map(e=>check('ids',esc(e.name),p.ids.includes(e.id)).replace('name="ids"',`name="ids" value="${e.id}"`)).join('')}<button class="primary sectiongap" type="submit">Save template</button></form>`,async f=>{state.settings.program[kind]={...p,name:f.get('name'),ids:f.getAll('ids')};await persist();render()})}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function backupDialog(){modal('Protect your progress',`<form>${field('pass','Backup passphrase (12+ characters)','','password','minlength="12" required autocomplete="new-password"')}${field('confirm','Repeat passphrase','','password','minlength="12" required autocomplete="new-password"')}<p class="smallprint sectiongap">AES-256-GCM encryption. Save your passphrase separately; nobody can recover it. After download, check Files and move the backup into iCloud Drive if desired.</p><button class="primary" type="submit">Encrypt & download</button></form>`,async f=>{if(f.get('pass')!==f.get('confirm'))throw Error('Passphrases do not match.');const snapshot=structuredClone(state);snapshot.settings.lastBackup=new Date().toISOString();const text=await encrypt(snapshot,f.get('pass'));const verified=await decrypt(text,f.get('pass'));if(JSON.stringify(verified)!==JSON.stringify(snapshot))throw Error('Backup verification failed.');download(text,`Chaps-Gym-${today()}.encrypted.json`,'application/json');state.settings.lastBackup=snapshot.settings.lastBackup;await persist();render();notify('Encrypted backup verified and download started. Confirm the file in Files.')})}
function restoreDialog(){modal('Restore encrypted backup',`<form><label>Backup file<input name="file" type="file" accept=".json,application/json" required></label>${field('pass','Passphrase','','password','required autocomplete="current-password"')}${check('replace','Replace current device data with this backup')}<p class="smallprint">Export your current data first if needed. The file is decrypted and validated locally before any replacement.</p><button class="primary" type="submit">Validate & restore</button></form>`,async f=>{if(!f.has('replace'))throw Error('Acknowledge replacement to restore.');const file=f.get('file');if(file.size>20*1024*1024)throw Error('Backup exceeds the 20 MB import limit.');const restored=await decrypt(await file.text(),f.get('pass'));await save(restored);state=restored;page='Today';render();notify('Backup restored successfully.')})}
function historyDialog(id){const w=state.sessions.find(w=>w.id===id);modal(esc(w.name),`<p class="smallprint">${fmt(w.date)} · ${esc(w.notes)}</p>${w.items.map(e=>`<div class="historyitem"><strong>${esc(e.name)} ${e.omitted?'(omitted)':''}</strong><p class="smallprint">${e.sets.filter(s=>s.done).map(s=>`${e.bodyweight?'BW':displayWeight(s.weight)+' '+state.settings.unit} × ${s.reps}${e.unilateral?' / side':''} · RIR ${s.rir} · RPE ${s.rpe}`).join('<br>')||'No completed sets'}</p></div>`).join('')}`)}
let audio;
function unlockAudio(){if(state.settings.sound){try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume()}catch{}}}
function alertTimer(){if(state.settings.sound&&audio){try{const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=740;g.gain.value=.08;o.start();o.stop(audio.currentTime+.4)}catch{}}if(state.settings.vibrate&&navigator.vibrate)navigator.vibrate([180,100,180])}
function renderTimer(){const box=$('#timer');if(!box)return;const t=state.timer;if(!t){box.innerHTML=state.active?'<div class="timerbar"><span class="smallprint">SESSION IN PROGRESS · SAVED LOCALLY</span><button class="small ghost" data-act="manualtimer">Start rest timer</button><button class="small primary" data-page="Train">Resume workout →</button></div>':'';return}let sec=timerRemaining(t);const digits=Math.floor(sec/60).toString().padStart(2,'0')+':'+(sec%60).toString().padStart(2,'0');box.innerHTML=`<div class="timerbar" role="region" aria-label="Rest timer"><div><div class="smallprint">${sec===0?'REST COMPLETE':t.paused?'REST PAUSED':'REST TIMER'} ${t.clockWarning?'· clock changed':''}</div><span class="timerdigits" role="timer" aria-label="${sec} seconds remaining">${digits}</span></div><div class="timercontrols"><button data-timer="adjust" data-seconds="-15" aria-label="Subtract 15 seconds">−15s</button><button data-timer="${t.paused?'resume':'pause'}">${t.paused?'Resume':'Pause'}</button><button data-timer="adjust" data-seconds="15">+15s</button><button data-timer="adjust" data-seconds="30">+30s</button><button data-timer="reset">Reset</button><button data-timer="skip">${sec===0?'Done':'Skip'}</button></div><span class="smallprint">Background alerts aren’t guaranteed on iPhone.</span></div>`}
function bind(){if($('#transition-rest'))$('#transition-rest').onchange=async e=>{const n=+e.target.value;if(n<0||n>300||!Number.isFinite(n))return notify('Transition rest must be 0–300 seconds.');state.active.transitionRest=n;await persist()};document.querySelectorAll('[data-set]').forEach(input=>input.oninput=input.onchange=async event=>{const [i,j,key]=input.dataset.set.split(',');const n=Number(input.value),max=key==='weight'?2000:key==='reps'?200:10;if(!Number.isFinite(n)||n<0||n>max||(key==='reps'&&n<1)){if(event.type==='change'){notify('Enter a valid value.');render()}return}state.active.items[i].sets[j][key]=key==='weight'?storedWeight(n):n;await persist()});document.querySelectorAll('[data-rest]').forEach(input=>input.onchange=async()=>{const n=+input.value;if(n<0||n>3600||!Number.isFinite(n)){notify('Rest must be 0–3600 seconds.');return}state.active.items[input.dataset.rest].rest=n;await persist()});if($('#session-notes'))$('#session-notes').onchange=async e=>{state.active.notes=e.target.value;await persist()};for(const [n,key]of [['workoutAuto','autoRest'],['superset','superset']]){const el=document.querySelector(`[name="${n}"]`);if(el)el.onchange=async()=>{state.active[key]=el.checked;await persist()}}if($('#phase-form'))$('#phase-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);state.settings.phase=f.get('phase');state.settings.offseasonStart=f.get('offseason');await persist();render()};if($('#settings-form'))$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);for(const k of ['autoRest','sound','vibrate','reduced','clearance','deload'])state.settings[k]=f.has(k);for(const k of ['unit','theme','priorities'])state.settings[k]=f.get(k);unlockAudio();await persist();render();notify('Preferences saved.')};if($('#equipment-form'))$('#equipment-form').onsubmit=async e=>{e.preventDefault();state.settings.equipment=new FormData(e.target).getAll('equipment');await persist();notify('Equipment saved for future workouts.')};for(const [sel,set]of [['#stats-period',v=>statsPeriod=v],['#stats-exercise',v=>statsExercise=v],['#stats-pattern',v=>statsPattern=v],['#stats-season',v=>statsSeason=v]])if($(sel))$(sel).onchange=e=>{set(e.target.value);render()};if($('#library-search'))$('#library-search').oninput=e=>{const pos=e.target.selectionStart;libraryQuery=e.target.value;render();$('#library-search').focus();$('#library-search').setSelectionRange(pos,pos)};document.querySelectorAll('[data-drag]').forEach(el=>{el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.drag);el.ondragover=e=>e.preventDefault();el.ondrop=async e=>{e.preventDefault();const from=e.dataTransfer.getData('text/plain'),to=el.dataset.drop;const source=plan(state,today(),14).find(x=>x.date===from);if(!source||source.done||source.kind==='G'||state.sessions.some(w=>w.date===to)||state.games.some(g=>!g.cancelled&&g.date===to))return notify('That move is unavailable. Use Change to choose another day.');state.overrides[from]='R';state.overrides[to]=source.kind;await persist();render()}})}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;unlockAudio();try{if(b.dataset.page){page=b.dataset.page;render();window.scrollTo(0,0);return}if(b.dataset.timer){state.timer=timerAction(state.timer,b.dataset.timer,+b.dataset.seconds||0);await persist();renderTimer();return}const a=b.dataset.act,i=+b.dataset.index,j=+b.dataset.setindex;switch(a){case'readiness':return readinessDialog();case'game':return gameDialog();case'editgame':return gameDialog(b.dataset.id);case'start':return await start(b.dataset.kind);case'conditioning':return conditioningDialog();case'move':return moveDialog(b.dataset.date);case'backup':return backupDialog();case'restore':return restoreDialog();case'csv':download(csv(state),`Chaps-Gym-${today()}.csv`,'text/csv');return;case'newexercise':return exerciseDialog();case'editexercise':return exerciseDialog(b.dataset.id);case'program':return programDialog(b.dataset.kind);case'history':return historyDialog(b.dataset.id);case'swap':return swapDialog(i);case'addexercise':return swapDialog(0,true);case'travel':return modal('Travel / unavailable day',`<form>${field('date','Date',today(),'date','required')}${check('available','Mark available again')}<button class="primary sectiongap" type="submit">Save availability</button></form>`,async f=>{const d=f.get('date');state.travel=state.travel.filter(x=>x!==d);if(!f.has('available'))state.travel.push(d);await persist();render()});case'persist':{const granted=await navigator.storage?.persist?.();$('#persistence-status').textContent=granted?'Durable storage granted. Keep making backups.':'Browser did not grant durable storage. Backups remain essential.';return}case'manualtimer':return modal('Start rest timer',`<form>${field('seconds','Rest seconds',90,'number','min="0" max="3600" required')}<button class="primary sectiongap" type="submit">Start timer</button></form>`,async f=>{state.timer=timerAction(null,'start',+f.get('seconds'));await persist();renderTimer()});case'exrest':state.timer=timerAction(null,'start',state.active.items[i].rest);break;case'addset':{const e=state.active.items[i];if(e.sets.length>=20)throw Error('Maximum 20 sets per exercise.');e.sets.push({weight:0,reps:e.reps,rir:3,rpe:7,done:false});break}case'copyset':{const e=state.active.items[i];const target=e.sets.findIndex(s=>!s.done);if(target<1)throw Error('Complete a set first; the next uncompleted set can copy it.');e.sets[target]={...e.sets[target-1],done:false};break}case'setdone':{const w=state.active,e=w.items[i],set=e.sets[j];if(!set.done){mayTrain(e);for(const input of document.querySelectorAll('[data-set]')){const [ei,sj,key]=input.dataset.set.split(',');if(+ei!==i||+sj!==j)continue;const n=Number(input.value),max=key==='weight'?2000:key==='reps'?200:10;if(input.value===''||!Number.isFinite(n)||n<0||n>max||(key==='reps'&&n<1))throw Error('Enter valid set values before completing.');set[key]=key==='weight'?storedWeight(n):n;}set.done=true;set.completedAt=Date.now();set.elapsedBetweenSets=state.lastSetAt?Math.max(0,Math.round((Date.now()-state.lastSetAt)/1000)):null;state.lastSetAt=Date.now();const rest=restAfterSet(w,i,j);if(w.autoRest)state.timer=timerAction(null,'start',rest)}else set.done=false;break}case'finish':{const w=state.active;if(!w.items.some(e=>e.sets.some(s=>s.done)))throw Error('Complete at least one set before finishing.');state.sessions.push({...structuredClone(w),finished:Date.now()});state.active=null;state.timer=null;await persist();render();notify('Session saved. Good work.');if(!state.settings.lastBackup||Date.now()-new Date(state.settings.lastBackup).getTime()>7*86400000)setTimeout(()=>notify('Backup reminder: download an encrypted backup from Settings.'),5500);return}case'discard':return modal('Discard this session?',`<p>Completed history is kept. Only the current unfinished session will be removed.</p><form><button class="primary" type="submit">Discard current session</button></form>`,async()=>{state.active=null;state.timer=null;await persist();render()});default:return}await persist();render()}catch(e){notify(e.message)}});
let lastTick=Date.now();setInterval(async()=>{const now=Date.now();if(state?.timer){if(now<lastTick-5000){const t=state.timer;state.timer={...t,paused:true,remaining:Math.min(t.duration,timerRemaining(t,lastTick)),clockWarning:true};await persist()}if(timerRemaining(state.timer,now)===0&&!state.timer.alerted&&!state.timer.paused){state.timer.alerted=true;alertTimer();notify('Rest complete. Ready when you are.');await persist()}renderTimer()}lastTick=now},500);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(state&&state.onboarded&&state.active?.date!==today())render();renderTimer()}});window.addEventListener('online',()=>state&&render());window.addEventListener('offline',()=>state&&render());
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{readyOffline=true;if(state)render()}).catch(()=>{});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!state)location.reload()})}try{state=await load();render()}catch(e){$('#app').innerHTML=`<div class="onboarding"><h1>Device storage unavailable</h1><p>Chaps Gym could not read its local database. Your stored data has not been overwritten. Try a normal Safari window and allow device storage.</p><p class="smallprint">${esc(e.message)}</p></div>`}
